const withStatus = (
  operation: DomainSyncOperation.SyncOperation,
  status: DomainSyncOperation.SyncOperationStatus
): DomainSyncOperation.SyncOperation => decodeSyncOperation({ ...encodeSyncOperation(operation), status });

const withTempDirectory = <A, E, R>(use: (tmpDir: string) => Effect.Effect<A, E, R>) =>
  Effect.acquireUseRelease(
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem;
      return yield* fs.makeTempDirectory();
    }),
    use,
    (tmpDir) =>
      Effect.gen(function* () {
        const fs = yield* FileSystem.FileSystem;
        yield* fs.remove(tmpDir, { recursive: true, force: true });
      })
  );

const withNativeDuckDbConnection = <A, E, R>(
  use: (connection: DuckDBConnection) => Effect.Effect<A, E, R>
): Effect.Effect<A, E, R> =>
  Effect.acquireUseRelease(
    Effect.promise(() =>
      DuckDBInstance.create(":memory:").then((instance) =>
        instance.connect().then((connection) => ({ connection, instance }))
      )
    ),
    ({ connection }) => use(connection),
    ({ connection, instance }) =>
      Effect.sync(() => {
        connection.closeSync();
        instance.closeSync();
      })
  );

