const withTempFixture = <A, E, R>(
  name: string,
  content: string,
  use: (file: string) => Effect.Effect<A, E, R>
): Effect.Effect<A, E | PlatformError, R | FileSystem.FileSystem | Path.Path> =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    return yield* Effect.acquireUseRelease(
      fs.makeTempDirectory(),
      (dir) =>
        Effect.gen(function* () {
          const file = path.join(dir, name);
          yield* fs.writeFileString(file, content);
          // Configure the fixture's temp directory as the streaming tools' only
          // allowed read root, so the path-safety guard is exercised against a
          // legitimate in-root read rather than blocking the test's temp file.
          return yield* use(file).pipe(Effect.provideService(StreamingAllowedRoots, [dir]));
        }),
      (dir) => Effect.orDie(fs.remove(dir, { force: true, recursive: true }))
    );
  });

const withObs = <A2, E>(
  handlers: Partial<Record<ObsRequestType, StubHandler>>,
  use: (obs: ObsShape, calls: Effect.Effect<ReadonlyArray<RecordedRequest>>) => Effect.Effect<A2, E>
): Effect.Effect<A2, E, Scope.Scope> =>
  Effect.gen(function* () {
    const stub = yield* makeStubProtocol(respondWith(handlers));
    const context = yield* Layer.build(Obs.layer.pipe(Layer.provide(Layer.succeed(ObsProtocol)(stub.protocol))));
    const obs = yield* Effect.service(Obs).pipe(Effect.provide(context));
    return yield* use(obs, stub.calls);
  });

const withLevel = (instance: ChalkInstance, level: ColorSupportLevelType, run: () => void): void => {
  const previousLevel = instance.level;

  try {
    instance.level = level;
    run();
  } finally {
    instance.level = previousLevel;
  }
};

