const withDisposition = (options: DispositionOptions, extra?: DispositionOptions) =>
  Effect.fnUntraced(function* () {
    const a = yield* observation("a", TEXT_A);
    const first = yield* dispositionFixture(10, targets(1, a), options);
    const dispositions =
      extra === undefined
        ? [first]
        : [first, yield* dispositionFixture(11, targets(1, a), { ...extra, supersedes: 10 })];
    return { dispositions, events: [yield* eventFixture(1, a)], sources: [sourceEntry(a)] } satisfies Fixture;
  });

const withEventOptions = (options: EventOptions) =>
  Effect.fnUntraced(function* () {
    const a = yield* observation("a", TEXT_A);
    return {
      dispositions: [yield* dispositionFixture(10, targets(1, a))],
      events: [yield* eventFixture(1, a, options)],
      sources: [sourceEntry(a)],
    } satisfies Fixture;
  });

const withToolkit = <A2, E>(
  run: (
    tools: OntologyToolServiceShape,
    path: OntologyFilePath,
    root: string
  ) => Effect.Effect<A2, E, FileSystem.FileSystem | Path.Path>
) =>
  Effect.fnUntraced(function* () {
    return yield* Effect.gen(function* () {
      const fileSystem = yield* FileSystem.FileSystem;
      const platformPath = yield* Path.Path;
      const root = yield* fileSystem.makeTempDirectoryScoped({ prefix: "beep-ontology-tools-" });
      yield* fileSystem.writeFileString(platformPath.join(root, "ontology.ttl"), fixtureSource);
      const path = yield* S.decodeEffect(OntologyFilePath)("ontology.ttl");
      return yield* Effect.gen(function* () {
        const tools = yield* OntologyToolService;
        return yield* run(tools, path, root);
      }).pipe(provideScopedLayer(toolLayerForRoot(root)));
    }).pipe(provideScopedLayer(NodeServices.layer));
  });

